// Dark-mode deck for Supplai — GBSN Social Logistics Challenge entry
// Palette (warm dark, terracotta): bg 16130F / ink EDE6D8 / faded 9A8F7E / accent E07A5F
const pptxgenjs = require('pptxgenjs');
const React = require('react');
const ReactDOMServer = require('react-dom/server');
const sharp = require('sharp');
const fs = require('fs');

const io = require('react-icons/io');
const md = require('react-icons/md');

const pptx = new pptxgenjs();
pptx.layout = pptxgenjs.LAYOUT_WIDE; // 13.333 x 7.5 in

const BG = "16130F";
const PANEL = "1F1B14";
const PANEL2 = "29231A";
const INK = "EDE6D8";
const FADED = "9A8F7E";
const ACCENT = "E07A5F";
const ACCENT_DK = "B85042";
const BORDER = "3A322A";
const WHITE = "FFFFFF";

const H = "Cambria";   // headers
const B = "Calibri";   // body

const W = 13.333, Hh = 7.5;
const MX = 0.55; // margin

// icon cache
const iconCache = {};
async function iconPng(Component, size = 30, color = ACCENT) {
  const key = (Component.displayName || Component.name || 'icon') + '|' + size + '|' + color;
  if (iconCache[key]) return iconCache[key];
  const svg = ReactDOMServer.renderToStaticMarkup(React.createElement(Component, { size, color }));
  const buf = await sharp(Buffer.from(svg)).resize(size * 4, size * 4).png().toBuffer();
  iconCache[key] = buf;
  return buf;
}

function fresh(o) { return JSON.parse(JSON.stringify(o)); }

// bg
function bg(slide, color = BG) {
  slide.addShape(pptxgenjs.ShapeType.Rectangle, {
    x: 0, y: 0, w: W, h: Hh,
    fill: { color },
    line: { type: 'none' },
    shadow: { type: 'none' },
  });
}

// rect helper
function rect(slide, { x, y, w, h, fill, line, radius, shadow = { type: 'none' } }) {
  return slide.addShape(pptxgenjs.ShapeType.RoundedRectangle, {
    x, y, w, h,
    rectRadius: radius || 6,
    fill: fill ? { color: fill } : { color: 'transparent' },
    line: line ? { color: line.color, width: line.width || 1 } : { type: 'none' },
    shadow: fresh(shadow),
  });
}

// text helper: textOrArray
function text(slide, items, { x, y, w, h, align = 'left', valign = 'middle', margin = 0, wrap = true, autofit = false } = {}) {
  const arr = Array.isArray(items) ? items : [{ text: items }];
  return slide.addText(arr.map(it => fresh({ text: it.text, ...it })), {
    x, y, w, h, align, valign, margin, wrap, autofit,
  });
}

// chip: small label pill
function chip(slide, { x, y, w = 1.6, h = 0.34, label, fill = ACCENT, color = BG, size = 11 }) {
  rect(slide, { x, y, w, h, fill, radius: 0.17 });
  text(slide, [{ text: label, font: B, fontSize: size, bold: true, color }], { x, y, w, h, align: 'center', valign: 'middle', margin: 0 });
}

// title block
function titleBlock(slide, kicker, title, sub) {
  let y = 0.42;
  if (kicker) {
    text(slide, [{ text: kicker, font: B, fontSize: 11, bold: true, color: ACCENT, charSpacing: 2 }], { x: MX, y, w: 10, h: 0.3, margin: 0 });
    y += 0.34;
  }
  text(slide, [{ text: title, font: H, fontSize: 33, bold: true, color: WHITE }], { x: MX, y, w: 10.5, h: 0.85, margin: 0, wrap: false });
  y += 0.95;
  if (sub) {
    text(slide, [{ text: sub, font: B, fontSize: 14, color: FADED }], { x: MX, y, w: 10.5, h: 0.4, margin: 0 });
    y += 0.5;
  }
  // accent rule (short, under title area) — not full width
  rect(slide, { x: MX, y: y - 0.12, w: 1.1, h: 0.045, fill: ACCENT, shadow: { type: 'none' } });
  return y + 0.25;
}

function footer(slide, n) {
  text(slide, [{ text: 'Supplai · GBSN Social Logistics Challenge · Health Track', font: B, fontSize: 8.5, color: FADED }], { x: MX, y: 7.08, w: 6, h: 0.25, margin: 0 });
  text(slide, [{ text: String(n), font: B, fontSize: 9, color: FADED, bold: true }], { x: W - MX - 0.5, y: 7.08, w: 0.5, h: 0.25, align: 'right', margin: 0 });
}

async function main() {
  // ============ S1: Title ============
  {
    const s = pptx.addSlide();
    bg(s);
    rect(s, { x: 0, y: 0, w: W, h: 0.14, fill: ACCENT, shadow: { type: 'none' } });
    rect(s, { x: 0, y: Hh - 0.14, w: W, h: 0.14, fill: ACCENT, shadow: { type: 'none' } });
    text(s, [{ text: 'GBSN SOCIAL LOGISTICS CHALLENGE 2026', font: B, fontSize: 13, bold: true, color: ACCENT, charSpacing: 3 }], { x: MX, y: 1.5, w: 10, h: 0.4, margin: 0 });
    text(s, [{ text: 'Supplai', font: H, fontSize: 56, bold: true, color: WHITE }], { x: MX, y: 2.05, w: 10, h: 1.1, margin: 0, wrap: false });
    text(s, [{ text: 'Lateral Medicine Stock-Sharing for Nigerian Primary Health Clinics', font: B, fontSize: 20, color: INK }], { x: MX, y: 3.2, w: 9.5, h: 0.5, margin: 0 });
    rect(s, { x: MX, y: 3.95, w: 1.6, h: 0.05, fill: ACCENT, shadow: { type: 'none' } });
    text(s, [{ text: 'SMS-first · confirm-before-dispatch · rider-delivered · LGA dashboard', font: B, fontSize: 12.5, color: FADED, italic: true }], { x: MX, y: 4.2, w: 10, h: 0.4, margin: 0 });
    text(s, [{ text: 'Health Track  ·  SDG 3.8  ·  29 October 2026', font: B, fontSize: 11, color: FADED }], { x: MX, y: 6.35, w: 10, h: 0.3, margin: 0 });
    s.addNotes('Title slide. Problem: Nigerian PHC stockouts. Solution: peer-to-peer lateral stock sharing.');
  }

  // ============ S2: Problem stats ============
  {
    const s = pptx.addSlide();
    bg(s);
    const y = titleBlock(s, 'The problem', 'Stockouts at Nigerian Primary Health Centres', 'Only about a third of essential medicines are actually on PHC shelves');
    // left text
    text(s, [
      { text: '~20,000 primary health facilities still track medicines on paper', font: B, fontSize: 14, color: INK, bold: true },
      { text: 'and order bimonthly. Stockouts surface late; resupply takes over two weeks.', font: B, fontSize: 14, color: FADED },
      { text: 'Meanwhile, surplus medicine sits unused — often expiring — in a neighbouring facility.', font: B, fontSize: 14, color: FADED },
    ], { x: MX, y, w: 5.6, h: 2.4, margin: 0, lineSpacing: 1.15 });
    // stat grid right
    const stats = [
      ['36.2%', 'essential medicines available at PHCs (NBS survey)'],
      ['65.7%', 'of essential medicines missing from PHC shelves'],
      ['41.7%', 'service delivery points stocked out of contraceptives in 3 months'],
      ['>2 weeks', 'resupply delay — strongest stockout predictor (OR 1.76)'],
    ];
    let sy = y;
    for (const [big, small] of stats) {
      rect(s, { x: 6.5, y: sy, w: 6.28, h: 0.98, fill: PANEL, line: { color: BORDER, width: 0.75 }, radius: 0.09, shadow: { type: 'none' } });
      text(s, [{ text: big, font: H, fontSize: 25, bold: true, color: ACCENT }], { x: 6.75, y: sy + 0.08, w: 2.6, h: 0.85, margin: 0 });
      text(s, [{ text: small, font: B, fontSize: 10.5, color: FADED }], { x: 9.5, y: sy + 0.12, w: 3.15, h: 0.8, margin: 0, lineSpacing: 1.05 });
      sy += 1.13;
    }
    footer(s, 2);
    s.addNotes('Evidence: NBS National Health Facility Survey (36.2% availability), contraceptive stockout study (41.7%, OR 1.76 for >2-week resupply).');
  }

  // ============ S3: Surplus paradox ============
  {
    const s = pptx.addSlide();
    bg(s);
    const y = titleBlock(s, 'The surplus paradox', 'The medicine is often nearby — but nobody knows', '');
    text(s, [
      { text: 'Clinic A is out of malaria drugs. A child waits.', font: B, fontSize: 14.5, color: INK, bold: true },
      { text: 'Clinic B, three kilometres away, has surplus stock nearing expiry.', font: B, fontSize: 14.5, color: INK },
      { text: 'Neither clinic knows the other exists in this respect. No channel connects them.', font: B, fontSize: 14.5, color: FADED },
    ], { x: MX, y, w: 6.2, h: 2.2, margin: 0, lineSpacing: 1.25 });
    // two facility cards
    rect(s, { x: 7.1, y: y, w: 2.75, h: 2.6, fill: PANEL, line: { color: BORDER, width: 0.75 }, radius: 0.08, shadow: { type: 'none' } });
    text(s, [{ text: 'CLINIC A', font: B, fontSize: 10, bold: true, color: ACCENT, charSpacing: 1 }], { x: 7.25, y: y + 0.18, w: 2.5, h: 0.3, margin: 0 });
    text(s, [{ text: 'Stocked out', font: H, fontSize: 20, bold: true, color: INK }], { x: 7.25, y: y + 0.5, w: 2.5, h: 0.5, margin: 0 });
    text(s, [{ text: 'Essential medicines absent.', font: B, fontSize: 11, color: FADED }], { x: 7.25, y: y + 1.1, w: 2.5, h: 0.9, margin: 0, lineSpacing: 1.1 });
    rect(s, { x: 10.15, y: y, w: 2.75, h: 2.6, fill: PANEL2, line: { color: ACCENT, width: 1 }, radius: 0.08, shadow: { type: 'none' } });
    text(s, [{ text: 'CLINIC B', font: B, fontSize: 10, bold: true, color: ACCENT, charSpacing: 1 }], { x: 10.3, y: y + 0.18, w: 2.5, h: 0.3, margin: 0 });
    text(s, [{ text: 'Surplus stock', font: H, fontSize: 20, bold: true, color: INK }], { x: 10.3, y: y + 0.5, w: 2.5, h: 0.5, margin: 0 });
    text(s, [{ text: 'Sitting unused, close to expiry.', font: B, fontSize: 11, color: FADED }], { x: 10.3, y: y + 1.1, w: 2.5, h: 0.9, margin: 0, lineSpacing: 1.1 });
    text(s, [{ text: '→', font: H, fontSize: 22, bold: true, color: ACCENT }], { x: 9.95, y: y + 1.15, w: 0.4, h: 0.4, margin: 0, align: 'center' });
    footer(s, 3);
    s.addNotes('Surplus paradox: redistribution is already recommended by government dashboards but no tool executes it at the PHC tier.');
  }

  // ============ S4: Why systems fail ============
  {
    const s = pptx.addSlide();
    bg(s);
    const y = titleBlock(s, 'Why today\'s systems fail', 'Paper, delay, and stale records', '');
    const cards = [
      ['Paper tracking', 'Bin cards not updated per transaction; records diverge from shelf reality.', ACCENT],
      ['Bimonthly ordering', 'Resupply takes over two weeks; stockouts surface too late.', ACCENT_DK],
      ['Stale LMIS data', 'Inventory accuracy is 70–87% — clinics promise drugs already sold.', ACCENT],
    ];
    let cx = MX;
    for (const [t, d, c] of cards) {
      rect(s, { x: cx, y, w: 4.0, h: 3.4, fill: PANEL, line: { color: BORDER, width: 0.75 }, radius: 0.07, shadow: { type: 'none' } });
      rect(s, { x: cx, y, w: 0.07, h: 3.4, fill: c, shadow: { type: 'none' } });
      text(s, [{ text: t, font: H, fontSize: 16, bold: true, color: WHITE }], { x: cx + 0.3, y: y + 0.3, w: 3.5, h: 0.4, margin: 0 });
      text(s, [{ text: d, font: B, fontSize: 12, color: FADED, lineSpacing: 1.2 }], { x: cx + 0.3, y: y + 0.9, w: 3.5, h: 2.2, margin: 0 });
      cx += 4.16;
    }
    rect(s, { x: MX, y: y + 3.7, w: 12.23, h: 0.85, fill: PANEL2, line: { color: ACCENT, width: 1 }, radius: 0.09, shadow: { type: 'none' } });
    text(s, [{ text: 'The failure mode: promise-first, verify-never — a clinic promises drugs its own records say are in stock but are already gone.', font: B, fontSize: 13, color: INK, italic: true }], { x: MX + 0.3, y: y + 3.85, w: 11.6, h: 0.6, margin: 0 });
    footer(s, 4);
    s.addNotes('LMIS data-quality studies (70–87% accuracy) show records not updated per transaction — confirm-before-dispatch attacks exactly this.');
  }

  // ============ S5: Solution flow ============
  {
    const s = pptx.addSlide();
    bg(s);
    const y = titleBlock(s, 'The solution', 'A stock-sharing network for clinics', 'Six steps, SMS-first, confirm-before-dispatch');
    const steps = [
      ['1', 'Report', 'Nurse SMS/WhatsApps drug name', md.MdLocalHospital],
      ['2', 'Match', 'Server fuzzy-matches drug name', md.MdInventory],
      ['3', 'Find', 'Nearby facilities with surplus', md.MdMap],
      ['4', 'Confirm', 'Recipient replies Y/N', md.MdCheckCircle],
      ['5', 'Deliver', 'Rider moves stock same day', md.MdLocalShipping],
      ['6', 'Track', 'Records update · LGA dashboard', md.MdDashboard],
    ];
    const stepW = 1.95, gap = 0.14, startX = MX;
    let sx = startX;
    for (let i = 0; i < steps.length; i++) {
      const [num, t, d, Comp] = steps[i];
      const buf = await iconPng(Comp, 26, ACCENT);
      s.addImage({ data: 'image/png;base64,' + buf.toString('base64'), x: sx + stepW / 2 - 0.16, y: y + 0.05, w: 0.32, h: 0.32 });
      rect(s, { x: sx, y: y + 0.5, w: stepW, h: 0.045, fill: BORDER, shadow: { type: 'none' } });
      text(s, [{ text: num, font: H, fontSize: 15, bold: true, color: ACCENT }], { x: sx, y: y + 0.65, w: stepW, h: 0.4, margin: 0, align: 'center' });
      text(s, [{ text: t, font: B, fontSize: 12.5, bold: true, color: WHITE }], { x: sx, y: y + 1.05, w: stepW, h: 0.3, margin: 0, align: 'center' });
      text(s, [{ text: d, font: B, fontSize: 9.5, color: FADED, lineSpacing: 1.05 }], { x: sx + 0.12, y: y + 1.4, w: stepW - 0.24, h: 1.1, margin: 0, align: 'center' });
      if (i < steps.length - 1) {
        text(s, [{ text: '→', font: H, fontSize: 14, bold: true, color: FADED }], { x: sx + stepW + 0.02, y: y + 1.0, w: 0.25, h: 0.4, margin: 0, align: 'center' });
      }
      sx += stepW + gap + 0.28; // include arrow space
    }
    rect(s, { x: MX, y: y + 2.85, w: 12.23, h: 0.75, fill: PANEL2, line: { color: ACCENT, width: 1 }, radius: 0.09, shadow: { type: 'none' } });
    text(s, [{ text: 'No smartphone, no app install: SMS and WhatsApp work on basic phones. Confirmation means no clinic ever promises drugs it no longer has.', font: B, fontSize: 12, color: INK }], { x: MX + 0.3, y: y + 2.95, w: 11.6, h: 0.6, margin: 0 });
    footer(s, 5);
    s.addNotes('Flow: SMS report → RxNorm/pg_trgm fuzzy match → nearby facilities → Y/N confirm → motorcycle rider POD → dashboard update.');
  }

  // ============ S6: Why it wins ============
  {
    const s = pptx.addSlide();
    bg(s);
    const y = titleBlock(s, 'Why this wins', 'A real gap, not a crowded space', '');
    const wins = [
      ['Confirm-before-dispatch', 'Fixes the stale-record failure mode documented in LMIS studies (70–87% accuracy).'],
      ['SMS-first', 'Works on basic phones — no smartphone, app, or data bundle needed at the clinic.'],
      ['Public PHC tier', 'Competitors serve private pharmacies or donations; none serve Nigeria\'s 20,000 public PHCs on basic phones.'],
      ['Complements government', 'Builds on DHIS2/OpenLMIS (already in Nigeria; saved 850,000 vaccine doses) instead of replacing it.'],
      ['Software + people + light hardware', 'Riders, nurses, health officers — mobilizable today, no heavy infrastructure.'],
    ];
    let wy = y;
    for (const [t, d] of wins) {
      rect(s, { x: MX, y: wy, w: 12.23, h: 0.82, fill: PANEL, line: { color: BORDER, width: 0.75 }, radius: 0.09, shadow: { type: 'none' } });
      rect(s, { x: MX, y: wy, w: 0.07, h: 0.82, fill: ACCENT, shadow: { type: 'none' } });
      text(s, [{ text: t, font: H, fontSize: 14, bold: true, color: WHITE }], { x: MX + 0.3, y: wy + 0.08, w: 3.6, h: 0.7, margin: 0 });
      text(s, [{ text: d, font: B, fontSize: 11.5, color: FADED, lineSpacing: 1.1 }], { x: MX + 4.1, y: wy + 0.1, w: 7.9, h: 0.65, margin: 0 });
      wy += 0.96;
    }
    footer(s, 6);
    s.addNotes('Positioning: SIRUM (US), InStockRx (US), MedCycle (Ghana), Remedial Health (Nigeria) validate the model; none covers public PHCs on basic phones.');
  }

  // ============ S7: Stack ============
  {
    const s = pptx.addSlide();
    bg(s);
    const y = titleBlock(s, 'Open-source stack', 'We build the connecting layer — not the whole system', '');
    const stack = [
      ['OpenBoxes / OpenLMIS', 'Inventory and stock records; OpenLMIS already runs in Nigeria and saved 850,000 vaccine doses from expiry.', io.IoIosMedical],
      ['Fleetbase', 'Rider dispatch, tracking, and proof of delivery.', md.MdLocalShipping],
      ['Africa\'s Talking', 'USSD / SMS / WhatsApp gateway for basic-phone clinics.', io.IoIosChatbubbles],
      ['RxNorm / pg_trgm', 'Fuzzy drug-name matching for misspelt SMS entries.', md.MdInventory],
    ];
    let sy2 = y;
