1: """
2: Helper for running LibreOffice (soffice) in environments where AF_UNIX
3: sockets may be blocked (e.g., sandboxed VMs).  Detects the restriction
4: at runtime and applies an LD_PRELOAD shim if needed.
5: 
6: Usage:
7:     from office.soffice import run_soffice
8: 
9:     result = run_soffice(["--headless", "--convert-to", "pdf", "input.docx"])
10: 
11: Call soffice through run_soffice, not through subprocess with get_soffice_env():
12: the env dict carries the shim but names no user profile, and a non-root sandbox
13: cannot bootstrap the default one -- soffice aborts with "User installation could
14: not be completed" and converts nothing. get_soffice_env() stays public for the
15: callers that build their own argv (they must pass -env:UserInstallation too).
16: """
17: 
18: import contextlib
19: import os
20: import socket
21: import subprocess
22: import tempfile
23: from collections.abc import Iterable
24: from pathlib import Path
25: 
26: 
27: def get_soffice_env() -> dict:
28:     env = os.environ.copy()
29:     env["SAL_USE_VCLPLUGIN"] = "svp"
30: 
31:     if _needs_shim():
32:         shim = _ensure_shim()
33:         env["LD_PRELOAD"] = str(shim)
34: 
35:     return env
36: 
37: 
38: def run_soffice(args: Iterable[str], **kwargs) -> subprocess.CompletedProcess:
39:     args = list(args)
40:     with contextlib.ExitStack() as stack:
41:         if not any(str(a).startswith("-env:UserInstallation") for a in args):
42:             profile = stack.enter_context(
43:                 tempfile.TemporaryDirectory(prefix="lo_profile_", ignore_cleanup_errors=True)
44:             )
45:             args = [f"-env:UserInstallation={Path(profile).as_uri()}"] + args
46:         return subprocess.run(["soffice"] + args, env=get_soffice_env(), **kwargs)
47: 
48: 
49: 
50: _SHIM_SO = Path(tempfile.gettempdir()) / "lo_socket_shim.so"
51: 
52: 
53: def _needs_shim() -> bool:
54:     try:
55:         s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
56:         s.close()
57:         return False
58:     except OSError:
59:         return True
60: 
61: 
62: def _ensure_shim() -> Path:
63:     if _SHIM_SO.exists():
64:         return _SHIM_SO
65: 
66:     src = Path(tempfile.gettempdir()) / "lo_socket_shim.c"
67:     src.write_text(_SHIM_SOURCE)
68:     subprocess.run(
69:         ["gcc", "-shared", "-fPIC", "-o", str(_SHIM_SO), str(src), "-ldl"],
70:         check=True,
71:         capture_output=True,
72:     )
73:     src.unlink()
74:     return _SHIM_SO
75: 
76: 
77: 
78: _SHIM_SOURCE = r"""
79: #define _GNU_SOURCE
80: #include <dlfcn.h>
