83: #include <stdio.h>
84: #include <stdlib.h>
85: #include <sys/socket.h>
86: #include <unistd.h>
87: 
88: static int (*real_socket)(int, int, int);
89: static int (*real_socketpair)(int, int, int, int[2]);
90: static int (*real_listen)(int, int);
91: static int (*real_accept)(int, struct sockaddr *, socklen_t *);
92: static int (*real_close)(int);
93: static int (*real_read)(int, void *, size_t);
