95: /* Per-FD bookkeeping (FDs >= 1024 are passed through unshimmed). */
96: static int is_shimmed[1024];
97: static int peer_of[1024];
98: static int wake_r[1024];            /* accept() blocks reading this */
99: static int wake_w[1024];            /* close()  writes to this      */
100: static int listener_fd = -1;        /* FD that received listen()    */
